// HD02 slice: the ALU54B operation table (D04). Generated by hd02_gen.py.
// Two MULT18X18D (every register bypassed) feed one ALU54B the way nextpnr
// needs it: A = {ROB, ROA} of m0, B = {ROB, ROA} of m1, MA = P of m0,
// MB = P of m1, SIGNEDIA/SIGNEDIB = their SIGNEDP. C and OP come from the
// fabric. Only the ALU's output and flag registers are on (CLK0, 25 MHz);
// CIN, CFB and SIGNEDCIN are not connected.
// Step n (0..16383): OP = n[13:3]; the operands are 130 fresh bits of a
// 168-bit LFSR: a0, b0, a1, b1 (18 bits each), c (54), and the signs
// sg = {SIGNEDB1, SIGNEDA1, SIGNEDB0, SIGNEDA0}. Everything holds still, then
// CE0..3 pulse together for one 25 MHz cycle: the output register captures
// once per step. 8 steps per opcode, one after another, so an operation
// that reads R back shows the previous line's R.
// Line "T<n:4 hex><sg:1><a0:5><b0:5><a1:5><b1:5><c:14><r:14><f:3>": r = R,
// f = {EQZ, EQZM, EQOM, EQPAT, EQPATB, OVER, UNDER, OVERUNDER, 0} after the
// pulse (SIGNEDR has no route to the fabric: it goes to the next ALU's
// SIGNEDCIN). The LFSR restarts at n = 0, so the pass repeats.
module top(input clk_25mhz, output ftdi_rxd);
  reg [167:0] l = 168'h1;
  reg [13:0] n = 0;
  wire [17:0] a0 = l[17:0], b0 = l[35:18], a1 = l[53:36], b1 = l[71:54];
  wire [53:0] c = l[125:72];
  wire [3:0] sg = l[129:126];
  wire [10:0] op = n[13:3];
  reg ce = 0;
  wire [35:0] p0, p1;
  wire [17:0] roa0, rob0, roa1, rob1;
  wire sp0, sp1;
  wire [53:0] r;
  wire eqz, eqzm, eqom, eqpat, eqpatb, over, under, overunder;

  MULT18X18D #(.REG_INPUTA_CLK("NONE"), .REG_INPUTB_CLK("NONE"), .REG_INPUTC_CLK("NONE"),
      .REG_PIPELINE_CLK("NONE"), .REG_OUTPUT_CLK("NONE"), .GSR("DISABLED"), .RESETMODE("SYNC"))
    m0(.A0(a0[0]), .A1(a0[1]), .A2(a0[2]), .A3(a0[3]), .A4(a0[4]), .A5(a0[5]), .A6(a0[6]), .A7(a0[7]), .A8(a0[8]), .A9(a0[9]), .A10(a0[10]), .A11(a0[11]), .A12(a0[12]), .A13(a0[13]), .A14(a0[14]), .A15(a0[15]), .A16(a0[16]), .A17(a0[17]), .B0(b0[0]), .B1(b0[1]), .B2(b0[2]), .B3(b0[3]), .B4(b0[4]), .B5(b0[5]), .B6(b0[6]), .B7(b0[7]), .B8(b0[8]), .B9(b0[9]), .B10(b0[10]), .B11(b0[11]), .B12(b0[12]), .B13(b0[13]), .B14(b0[14]), .B15(b0[15]), .B16(b0[16]), .B17(b0[17]),
      .SIGNEDA(sg[0]), .SIGNEDB(sg[1]), .SOURCEA(1'b0), .SOURCEB(1'b0),
      .CLK0(clk_25mhz), .CLK1(1'b0), .CLK2(1'b0), .CLK3(1'b0),
      .CE0(ce), .CE1(ce), .CE2(ce), .CE3(ce), .RST0(1'b0), .RST1(1'b0), .RST2(1'b0), .RST3(1'b0),
      .P0(p0[0]), .P1(p0[1]), .P2(p0[2]), .P3(p0[3]), .P4(p0[4]), .P5(p0[5]), .P6(p0[6]), .P7(p0[7]), .P8(p0[8]), .P9(p0[9]), .P10(p0[10]), .P11(p0[11]), .P12(p0[12]), .P13(p0[13]), .P14(p0[14]), .P15(p0[15]), .P16(p0[16]), .P17(p0[17]), .P18(p0[18]), .P19(p0[19]), .P20(p0[20]), .P21(p0[21]), .P22(p0[22]), .P23(p0[23]), .P24(p0[24]), .P25(p0[25]), .P26(p0[26]), .P27(p0[27]), .P28(p0[28]), .P29(p0[29]), .P30(p0[30]), .P31(p0[31]), .P32(p0[32]), .P33(p0[33]), .P34(p0[34]), .P35(p0[35]), .ROA0(roa0[0]), .ROA1(roa0[1]), .ROA2(roa0[2]), .ROA3(roa0[3]), .ROA4(roa0[4]), .ROA5(roa0[5]), .ROA6(roa0[6]), .ROA7(roa0[7]), .ROA8(roa0[8]), .ROA9(roa0[9]), .ROA10(roa0[10]), .ROA11(roa0[11]), .ROA12(roa0[12]), .ROA13(roa0[13]), .ROA14(roa0[14]), .ROA15(roa0[15]), .ROA16(roa0[16]), .ROA17(roa0[17]), .ROB0(rob0[0]), .ROB1(rob0[1]), .ROB2(rob0[2]), .ROB3(rob0[3]), .ROB4(rob0[4]), .ROB5(rob0[5]), .ROB6(rob0[6]), .ROB7(rob0[7]), .ROB8(rob0[8]), .ROB9(rob0[9]), .ROB10(rob0[10]), .ROB11(rob0[11]), .ROB12(rob0[12]), .ROB13(rob0[13]), .ROB14(rob0[14]), .ROB15(rob0[15]), .ROB16(rob0[16]), .ROB17(rob0[17]), .SIGNEDP(sp0));

  MULT18X18D #(.REG_INPUTA_CLK("NONE"), .REG_INPUTB_CLK("NONE"), .REG_INPUTC_CLK("NONE"),
      .REG_PIPELINE_CLK("NONE"), .REG_OUTPUT_CLK("NONE"), .GSR("DISABLED"), .RESETMODE("SYNC"))
    m1(.A0(a1[0]), .A1(a1[1]), .A2(a1[2]), .A3(a1[3]), .A4(a1[4]), .A5(a1[5]), .A6(a1[6]), .A7(a1[7]), .A8(a1[8]), .A9(a1[9]), .A10(a1[10]), .A11(a1[11]), .A12(a1[12]), .A13(a1[13]), .A14(a1[14]), .A15(a1[15]), .A16(a1[16]), .A17(a1[17]), .B0(b1[0]), .B1(b1[1]), .B2(b1[2]), .B3(b1[3]), .B4(b1[4]), .B5(b1[5]), .B6(b1[6]), .B7(b1[7]), .B8(b1[8]), .B9(b1[9]), .B10(b1[10]), .B11(b1[11]), .B12(b1[12]), .B13(b1[13]), .B14(b1[14]), .B15(b1[15]), .B16(b1[16]), .B17(b1[17]),
      .SIGNEDA(sg[2]), .SIGNEDB(sg[3]), .SOURCEA(1'b0), .SOURCEB(1'b0),
      .CLK0(clk_25mhz), .CLK1(1'b0), .CLK2(1'b0), .CLK3(1'b0),
      .CE0(ce), .CE1(ce), .CE2(ce), .CE3(ce), .RST0(1'b0), .RST1(1'b0), .RST2(1'b0), .RST3(1'b0),
      .P0(p1[0]), .P1(p1[1]), .P2(p1[2]), .P3(p1[3]), .P4(p1[4]), .P5(p1[5]), .P6(p1[6]), .P7(p1[7]), .P8(p1[8]), .P9(p1[9]), .P10(p1[10]), .P11(p1[11]), .P12(p1[12]), .P13(p1[13]), .P14(p1[14]), .P15(p1[15]), .P16(p1[16]), .P17(p1[17]), .P18(p1[18]), .P19(p1[19]), .P20(p1[20]), .P21(p1[21]), .P22(p1[22]), .P23(p1[23]), .P24(p1[24]), .P25(p1[25]), .P26(p1[26]), .P27(p1[27]), .P28(p1[28]), .P29(p1[29]), .P30(p1[30]), .P31(p1[31]), .P32(p1[32]), .P33(p1[33]), .P34(p1[34]), .P35(p1[35]), .ROA0(roa1[0]), .ROA1(roa1[1]), .ROA2(roa1[2]), .ROA3(roa1[3]), .ROA4(roa1[4]), .ROA5(roa1[5]), .ROA6(roa1[6]), .ROA7(roa1[7]), .ROA8(roa1[8]), .ROA9(roa1[9]), .ROA10(roa1[10]), .ROA11(roa1[11]), .ROA12(roa1[12]), .ROA13(roa1[13]), .ROA14(roa1[14]), .ROA15(roa1[15]), .ROA16(roa1[16]), .ROA17(roa1[17]), .ROB0(rob1[0]), .ROB1(rob1[1]), .ROB2(rob1[2]), .ROB3(rob1[3]), .ROB4(rob1[4]), .ROB5(rob1[5]), .ROB6(rob1[6]), .ROB7(rob1[7]), .ROB8(rob1[8]), .ROB9(rob1[9]), .ROB10(rob1[10]), .ROB11(rob1[11]), .ROB12(rob1[12]), .ROB13(rob1[13]), .ROB14(rob1[14]), .ROB15(rob1[15]), .ROB16(rob1[16]), .ROB17(rob1[17]), .SIGNEDP(sp1));

  ALU54B #(.REG_OUTPUT0_CLK("CLK0"), .REG_OUTPUT1_CLK("CLK0"), .REG_FLAG_CLK("CLK0"),
      .GSR("DISABLED"), .RESETMODE("SYNC"),
      .MCPAT("0x1555555555555A"), .MASKPAT("0x3FFFFFFFFFFFF0"), .MASK01("0x3FFFFFFFFFFF0F"), .RNDPAT("0x0123456789ABC5"))
    alu(.A0(roa0[0]), .A1(roa0[1]), .A2(roa0[2]), .A3(roa0[3]), .A4(roa0[4]), .A5(roa0[5]), .A6(roa0[6]), .A7(roa0[7]), .A8(roa0[8]), .A9(roa0[9]), .A10(roa0[10]), .A11(roa0[11]), .A12(roa0[12]), .A13(roa0[13]), .A14(roa0[14]), .A15(roa0[15]), .A16(roa0[16]), .A17(roa0[17]), .A18(rob0[0]), .A19(rob0[1]), .A20(rob0[2]), .A21(rob0[3]), .A22(rob0[4]), .A23(rob0[5]), .A24(rob0[6]), .A25(rob0[7]), .A26(rob0[8]), .A27(rob0[9]), .A28(rob0[10]), .A29(rob0[11]), .A30(rob0[12]), .A31(rob0[13]), .A32(rob0[14]), .A33(rob0[15]), .A34(rob0[16]), .A35(rob0[17]),
      .B0(roa1[0]), .B1(roa1[1]), .B2(roa1[2]), .B3(roa1[3]), .B4(roa1[4]), .B5(roa1[5]), .B6(roa1[6]), .B7(roa1[7]), .B8(roa1[8]), .B9(roa1[9]), .B10(roa1[10]), .B11(roa1[11]), .B12(roa1[12]), .B13(roa1[13]), .B14(roa1[14]), .B15(roa1[15]), .B16(roa1[16]), .B17(roa1[17]), .B18(rob1[0]), .B19(rob1[1]), .B20(rob1[2]), .B21(rob1[3]), .B22(rob1[4]), .B23(rob1[5]), .B24(rob1[6]), .B25(rob1[7]), .B26(rob1[8]), .B27(rob1[9]), .B28(rob1[10]), .B29(rob1[11]), .B30(rob1[12]), .B31(rob1[13]), .B32(rob1[14]), .B33(rob1[15]), .B34(rob1[16]), .B35(rob1[17]),
      .MA0(p0[0]), .MA1(p0[1]), .MA2(p0[2]), .MA3(p0[3]), .MA4(p0[4]), .MA5(p0[5]), .MA6(p0[6]), .MA7(p0[7]), .MA8(p0[8]), .MA9(p0[9]), .MA10(p0[10]), .MA11(p0[11]), .MA12(p0[12]), .MA13(p0[13]), .MA14(p0[14]), .MA15(p0[15]), .MA16(p0[16]), .MA17(p0[17]), .MA18(p0[18]), .MA19(p0[19]), .MA20(p0[20]), .MA21(p0[21]), .MA22(p0[22]), .MA23(p0[23]), .MA24(p0[24]), .MA25(p0[25]), .MA26(p0[26]), .MA27(p0[27]), .MA28(p0[28]), .MA29(p0[29]), .MA30(p0[30]), .MA31(p0[31]), .MA32(p0[32]), .MA33(p0[33]), .MA34(p0[34]), .MA35(p0[35]), .MB0(p1[0]), .MB1(p1[1]), .MB2(p1[2]), .MB3(p1[3]), .MB4(p1[4]), .MB5(p1[5]), .MB6(p1[6]), .MB7(p1[7]), .MB8(p1[8]), .MB9(p1[9]), .MB10(p1[10]), .MB11(p1[11]), .MB12(p1[12]), .MB13(p1[13]), .MB14(p1[14]), .MB15(p1[15]), .MB16(p1[16]), .MB17(p1[17]), .MB18(p1[18]), .MB19(p1[19]), .MB20(p1[20]), .MB21(p1[21]), .MB22(p1[22]), .MB23(p1[23]), .MB24(p1[24]), .MB25(p1[25]), .MB26(p1[26]), .MB27(p1[27]), .MB28(p1[28]), .MB29(p1[29]), .MB30(p1[30]), .MB31(p1[31]), .MB32(p1[32]), .MB33(p1[33]), .MB34(p1[34]), .MB35(p1[35]),
      .C0(c[0]), .C1(c[1]), .C2(c[2]), .C3(c[3]), .C4(c[4]), .C5(c[5]), .C6(c[6]), .C7(c[7]), .C8(c[8]), .C9(c[9]), .C10(c[10]), .C11(c[11]), .C12(c[12]), .C13(c[13]), .C14(c[14]), .C15(c[15]), .C16(c[16]), .C17(c[17]), .C18(c[18]), .C19(c[19]), .C20(c[20]), .C21(c[21]), .C22(c[22]), .C23(c[23]), .C24(c[24]), .C25(c[25]), .C26(c[26]), .C27(c[27]), .C28(c[28]), .C29(c[29]), .C30(c[30]), .C31(c[31]), .C32(c[32]), .C33(c[33]), .C34(c[34]), .C35(c[35]), .C36(c[36]), .C37(c[37]), .C38(c[38]), .C39(c[39]), .C40(c[40]), .C41(c[41]), .C42(c[42]), .C43(c[43]), .C44(c[44]), .C45(c[45]), .C46(c[46]), .C47(c[47]), .C48(c[48]), .C49(c[49]), .C50(c[50]), .C51(c[51]), .C52(c[52]), .C53(c[53]), .OP0(op[0]), .OP1(op[1]), .OP2(op[2]), .OP3(op[3]), .OP4(op[4]), .OP5(op[5]), .OP6(op[6]), .OP7(op[7]), .OP8(op[8]), .OP9(op[9]), .OP10(op[10]),
      .SIGNEDIA(sp0), .SIGNEDIB(sp1),
      .CLK0(clk_25mhz), .CLK1(1'b0), .CLK2(1'b0), .CLK3(1'b0),
      .CE0(ce), .CE1(ce), .CE2(ce), .CE3(ce), .RST0(1'b0), .RST1(1'b0), .RST2(1'b0), .RST3(1'b0),
      .R0(r[0]), .R1(r[1]), .R2(r[2]), .R3(r[3]), .R4(r[4]), .R5(r[5]), .R6(r[6]), .R7(r[7]), .R8(r[8]), .R9(r[9]), .R10(r[10]), .R11(r[11]), .R12(r[12]), .R13(r[13]), .R14(r[14]), .R15(r[15]), .R16(r[16]), .R17(r[17]), .R18(r[18]), .R19(r[19]), .R20(r[20]), .R21(r[21]), .R22(r[22]), .R23(r[23]), .R24(r[24]), .R25(r[25]), .R26(r[26]), .R27(r[27]), .R28(r[28]), .R29(r[29]), .R30(r[30]), .R31(r[31]), .R32(r[32]), .R33(r[33]), .R34(r[34]), .R35(r[35]), .R36(r[36]), .R37(r[37]), .R38(r[38]), .R39(r[39]), .R40(r[40]), .R41(r[41]), .R42(r[42]), .R43(r[43]), .R44(r[44]), .R45(r[45]), .R46(r[46]), .R47(r[47]), .R48(r[48]), .R49(r[49]), .R50(r[50]), .R51(r[51]), .R52(r[52]), .R53(r[53]),
      .EQZ(eqz), .EQZM(eqzm), .EQOM(eqom), .EQPAT(eqpat), .EQPATB(eqpatb),
      .OVER(over), .UNDER(under), .OVERUNDER(overunder));

  // The line: 56 hex digits after "T".
  wire [223:0] line = {{2{1'b0}}, n, sg, 2'b0, a0, 2'b0, b0, 2'b0, a1, 2'b0, b1, 2'b0, c, 2'b0, r,
                       3'b0, eqz, eqzm, eqom, eqpat, eqpatb, over, under, overunder, 1'b0};
  reg [223:0] held = 0;
  function [7:0] hex(input [3:0] v);
    hex = v < 10 ? 8'h30 + v : 8'h37 + v;
  endfunction
  reg [5:0] ci = 0;
  reg [7:0] ch;
  always @* begin
    if (ci == 0) ch = "T";
    else if (ci < 57) ch = hex(held[223 - 4 * (ci - 1) -: 4]);
    else if (ci == 57) ch = 8'h0d;
    else ch = 8'h0a;
  end
  localparam SHIFT = 0, SETTLE = 1, PULSE = 2, HOLD = 3, SEND = 4;
  reg [2:0] state = SHIFT;
  reg [8:0] k = 0;
  reg tx = 1, busy = 0;
  reg [7:0] baud = 0;
  reg [3:0] bitn = 0;
  reg [9:0] shift = 10'h3ff;
  always @(posedge clk_25mhz) begin
    ce <= 0;
    case (state)
      SHIFT: begin  // 168 shifts: every operand bit is new
        l <= {l[166:0], l[167] ^ l[165] ^ l[152] ^ l[150]};
        k <= k + 1;
        if (k == 167) begin k <= 0; state <= SETTLE; end
      end
      SETTLE: begin k <= k + 1; if (k == 7) begin k <= 0; state <= PULSE; end end
      PULSE: begin ce <= 1; state <= HOLD; end
      HOLD: begin k <= k + 1; if (k == 7) begin k <= 0; held <= line; state <= SEND; end end
      SEND:
        if (!busy) begin
          shift <= {1'b1, ch, 1'b0};
          busy <= 1; baud <= 0; bitn <= 0;
        end else if (baud == 216) begin
          baud <= 0;
          tx <= shift[0];
          shift <= {1'b1, shift[9:1]};
          bitn <= bitn + 1;
          if (bitn == 9) begin
            busy <= 0;
            if (ci == 58) begin
              ci <= 0;
              n <= n + 1;
              if (&n) l <= 168'h1;
              state <= SHIFT;
            end else ci <= ci + 1;
          end
        end else baud <= baud + 1;
      default: state <= SHIFT;
    endcase
  end
  assign ftdi_rxd = tx;
endmodule
